CREATE TABLE point_de_vente (
	id_point_de_vente INTEGER NOT NULL, 
	nom VARCHAR(120) NOT NULL, 
	ville VARCHAR(120) NOT NULL, 
	PRIMARY KEY (id_point_de_vente)
);
INSERT INTO "point_de_vente" VALUES(1,'Nanterre','Nanterre');
CREATE TABLE produit (
	id_produit INTEGER NOT NULL, 
	nom VARCHAR(120) NOT NULL, 
	categorie VARCHAR(80), 
	prix_unitaire NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id_produit)
);
INSERT INTO "produit" VALUES(1,'Reine','Pizza',13.9);
INSERT INTO "produit" VALUES(2,'Pepperoni','Pizza',14.9);
INSERT INTO "produit" VALUES(3,'4 Fromages','Pizza',15.9);
INSERT INTO "produit" VALUES(4,'Végétarienne','Pizza',13.5);
INSERT INTO "produit" VALUES(5,'Calzone','Pizza',14.5);
INSERT INTO "produit" VALUES(6,'Margherita','Pizza',11.9);
INSERT INTO "produit" VALUES(7,'Boisson 33cl','Boisson',2.5);
INSERT INTO "produit" VALUES(8,'Tiramisu','Dessert',4.9);
CREATE TABLE utilisateur (
	id_utilisateur INTEGER NOT NULL, 
	point_de_vente_id INTEGER, 
	nom VARCHAR(120) NOT NULL, 
	email VARCHAR(180) NOT NULL, 
	role VARCHAR(40) NOT NULL, 
	actif BOOLEAN NOT NULL, 
	mot_de_passe_hash VARCHAR(255) NOT NULL, 
	PRIMARY KEY (id_utilisateur), 
	FOREIGN KEY(point_de_vente_id) REFERENCES point_de_vente (id_point_de_vente)
);
